import java.util.UUID;

// Simple immutable container for request-scoped data.
class RequestContext {
    private final String userId;
    private final String traceId;

    public RequestContext(String userId, String traceId) {
        this.userId = userId;
        this.traceId = traceId;
    }

    public String getUserId() {
        return userId;
    }

    public String getTraceId() {
        return traceId;
    }
}

// Repository layer, the deepest layer in the call chain.
class OrderRepository {
    public void save(RequestContext context, String orderId) {
        // Reads from the exact same context object the controller created.
        System.out.println("[Repository] traceId=" + context.getTraceId() + " saving order " + orderId + " for user " + context.getUserId());
    }
}

// Service layer, sits between the controller and the repository.
class OrderService {
    private final OrderRepository repository = new OrderRepository();

    public void placeOrder(RequestContext context, String orderId) {
        System.out.println("[Service] traceId=" + context.getTraceId() + " processing order " + orderId);
        // Forwards the same context reference further down, never a copy.
        repository.save(context, orderId);
    }
}

// Controller layer, the entry point where the request context is born.
class OrderController {
    private final OrderService service = new OrderService();

    public void handleRequest(RequestContext context, String orderId) {
        System.out.println("[Controller] traceId=" + context.getTraceId() + " received request for order " + orderId);
        service.placeOrder(context, orderId);
    }
}

public class Main {
    public static void main(String[] args) {
        // The context is created exactly once, right when the request starts.
        RequestContext context = new RequestContext("user-42", UUID.randomUUID().toString());

        OrderController controller = new OrderController();
        controller.handleRequest(context, "order-1001");
    }
}

