import uuid


class RequestContext:
    # Simple immutable container for request-scoped data.
    def __init__(self, user_id, trace_id):
        self.user_id = user_id
        self.trace_id = trace_id


class OrderRepository:
    # Repository layer, the deepest layer in the call chain.
    def save(self, context, order_id):
        # Reads from the exact same context object the controller created.
        print(f"[Repository] traceId={context.trace_id} saving order {order_id} for user {context.user_id}")


class OrderService:
    # Service layer, sits between the controller and the repository.
    def __init__(self):
        self.repository = OrderRepository()

    def place_order(self, context, order_id):
        print(f"[Service] traceId={context.trace_id} processing order {order_id}")
        # Forwards the same context object further down, never a copy.
        self.repository.save(context, order_id)


class OrderController:
    # Controller layer, the entry point where the request context is born.
    def __init__(self):
        self.service = OrderService()

    def handle_request(self, context, order_id):
        print(f"[Controller] traceId={context.trace_id} received request for order {order_id}")
        self.service.place_order(context, order_id)


if __name__ == "__main__":
    # The context is created exactly once, right when the request starts.
    context = RequestContext("user-42", str(uuid.uuid4()))

    controller = OrderController()
    controller.handle_request(context, "order-1001")

