#include <iostream>
#include <string>
using namespace std;

// Simple immutable container for request-scoped data.
class RequestContext {
private:
    string userId;
    string traceId;
public:
    RequestContext(string userId, string traceId) : userId(userId), traceId(traceId) {}

    string getUserId() const { return userId; }
    string getTraceId() const { return traceId; }
};

// Repository layer, the deepest layer in the call chain.
class OrderRepository {
public:
    void save(const RequestContext& context, const string& orderId) {
        // Reads from the exact same context object the controller created.
        cout << "[Repository] traceId=" << context.getTraceId() << " saving order " << orderId << " for user " << context.getUserId() << endl;
    }
};

// Service layer, sits between the controller and the repository.
class OrderService {
private:
    OrderRepository repository;
public:
    void placeOrder(const RequestContext& context, const string& orderId) {
        cout << "[Service] traceId=" << context.getTraceId() << " processing order " << orderId << endl;
        // Forwards the same context by reference, never a copy.
        repository.save(context, orderId);
    }
};

// Controller layer, the entry point where the request context is born.
class OrderController {
private:
    OrderService service;
public:
    void handleRequest(const RequestContext& context, const string& orderId) {
        cout << "[Controller] traceId=" << context.getTraceId() << " received request for order " << orderId << endl;
        service.placeOrder(context, orderId);
    }
};

int main() {
    // The context is created exactly once, right when the request starts.
    RequestContext context("user-42", "trace-7f3ac9e1");

    OrderController controller;
    controller.handleRequest(context, "order-1001");

    return 0;
}
